    form.querySelectorAll("[data-g]").forEach(b=>b.onclick=()=>{ clearGhost(); const g=JSON.parse(hh[+b.dataset.g].geom); ghost=L.geoJSON({type:"Feature",geometry:g},{style:{color:"#f1e9d8",weight:2,dashArray:"5 5",fillOpacity:.05},pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:8,color:"#f1e9d8",dashArray:"3 3",fill:false})}).addTo(map); toast&&toast(T.ghost); });
