  <div class="meas"><div class="t">${T.measures}</div>${m.area!=null?`<div><span>${T.area_}</span><b>${fmt(m.area,2)} m²</b></div><div><span>${T.per}</span><b>${fmt(m.per,2)} m</b></div>`:`<div><span>${T.len}</span><b>${fmt(m.len,2)} m</b></div>`}</div>
