  const rd=()=>{ const g=id=>{ const el=form.querySelector("#"+id); return el?+el.value:null; }; const kk=SH.unit==="cm"?1/100:1; if(g("sa")!=null) SH.a=g("sa")*kk; if(g("sb")!=null) SH.b=g("sb")*kk; if(g("sr")!=null) SH.r=g("sr")*kk; if(g("ss")!=null) SH.side=g("ss")*kk; if(g("sl")!=null) SH.len=g("sl")*kk; if(g("sn")!=null) SH.n=g("sn"); SH.rot=g("srot")||0; SH.snap=form.querySelector("#ssnap").checked; const sf=form.querySelector("#ssnapf"); if(sf) SH.snapF=sf.checked; };
